  Future<DateTime?> oldestPendingMailSince(String id) async {
    final sentAts = <String>[
      for (final m in await pendingInbox(id)) m.sentAt,
      for (final m
          in _handles[id]?.pendingMessages ?? const <SubagentMessage>[])
        m.sentAt,
